#[cfg(all(target_os = "linux", test))]
type B22AfterEarlyNotAcceptedHook = Box<dyn FnOnce() + Send + 'static>;

#[cfg(all(target_os = "linux", test))]
static B22_AFTER_EARLY_NOT_ACCEPTED_HOOK: LazyLock<Mutex<Option<B22AfterEarlyNotAcceptedHook>>> =
    LazyLock::new(|| Mutex::new(None));

#[cfg(all(target_os = "linux", test))]
fn set_b2_2_after_early_not_accepted_hook(hook: B22AfterEarlyNotAcceptedHook) {
    *B22_AFTER_EARLY_NOT_ACCEPTED_HOOK
        .lock()
        .expect("B2.2 early NotAccepted hook mutex poisoned") = Some(hook);
}

#[cfg(all(target_os = "linux", test))]
fn run_b2_2_after_early_not_accepted_hook() {
    if let Some(hook) = B22_AFTER_EARLY_NOT_ACCEPTED_HOOK
        .lock()
        .expect("B2.2 early NotAccepted hook mutex poisoned")
        .take()
    {
        hook();
    }
}

#[cfg(target_os = "linux")]
fn stop_order_probe_log(
    session_id: &str,
    participant_id: Option<&str>,
    event: &str,
    fields: serde_json::Value,
) {
    let Ok(filtered_session_id) = std::env::var("SUBSTRATE_STOP_ORDER_DEBUG_SESSION") else {
        return;
    };
    if filtered_session_id != session_id {
        return;
    }
    if let Ok(filtered_participant_id) = std::env::var("SUBSTRATE_STOP_ORDER_DEBUG_PARTICIPANT") {
        if participant_id != Some(filtered_participant_id.as_str()) {
            return;
        }
    }
    let log_path = std::env::var("SUBSTRATE_STOP_ORDER_DEBUG_LOG")
        .unwrap_or_else(|_| "/tmp/substrate-stop-order-debug.jsonl".to_string());
    let record = serde_json::json!({
        "ts": chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true),
        "pid": std::process::id(),
        "event": event,
        "session_id": session_id,
        "participant_id": participant_id,
        "fields": fields,
    });
    let Ok(mut file) = OpenOptions::new().create(true).append(true).open(log_path) else {
        return;
    };
    let _ = writeln!(file, "{record}");
}

