#[cfg(target_os = "linux")]
async fn wait_for_stop_world_worker_closeout(
    store: &AgentRuntimeStateStore,
    orchestration_session_id: &str,
    participant_id: &str,
) -> Result<RetainedWorkerStopCloseoutV1> {
    let started_at = Instant::now();
    loop {
        let participant = store.load_participant(participant_id)?.ok_or_else(|| {
            anyhow::anyhow!(
                "missing_target_participant: retained worker {} disappeared before durable stop closeout was observed",
                participant_id
            )
        })?;
        if retained_worker_stop_terminal_proof_observed(&participant) {
            let session = store
                .load_orchestration_session(orchestration_session_id)?
                .ok_or_else(|| {
                    anyhow::anyhow!(
                        "missing_orchestration_session: orchestration session {} disappeared before durable stop closeout was observed",
                        orchestration_session_id
                    )
                })?;
            return Ok(RetainedWorkerStopCloseoutV1 {
                participant_state: participant.handle.state,
                session_state: session.state,
            });
        }
        if participant.handle.state != AgentRuntimeSessionState::Stopped
            && !participant.handle.state.is_live()
        {
            anyhow::bail!(
                "stop_closeout_failed: retained worker {} reached terminal state {} instead of stopped",
                participant_id,
                agent_runtime_session_state_label(&participant.handle.state)
            );
        }
        if started_at.elapsed() >= STOP_WORLD_WORKER_CLOSEOUT_WAIT_TIMEOUT {
            anyhow::bail!(
                "owner_unreachable: timed out waiting for retained worker {} to reach durable stopped closeout",
                participant_id
            );
        }
        tokio::time::sleep(STOP_WORLD_WORKER_CLOSEOUT_POLL_INTERVAL).await;
    }
}

#[cfg(target_os = "linux")]
fn retained_worker_stop_terminal_proof_observed(
    participant: &AgentRuntimeParticipantRecord,
) -> bool {
    participant.handle.state == AgentRuntimeSessionState::Stopped
        && participant.internal.terminal_observed_at.is_some()
        && participant.internal.termination_reason.is_some()
}

#[cfg(target_os = "linux")]
fn observed_stop_world_worker_closeout(
    store: &AgentRuntimeStateStore,
    orchestration_session_id: &str,
    participant_id: &str,
) -> Result<Option<RetainedWorkerStopCloseoutV1>> {
    let Some(participant) = store.load_participant(participant_id)? else {
        return Ok(None);
    };
    if !retained_worker_stop_terminal_proof_observed(&participant) {
        return Ok(None);
    }
    let Some(session) = store.load_orchestration_session(orchestration_session_id)? else {
        return Ok(None);
    };
    Ok(Some(RetainedWorkerStopCloseoutV1 {
        participant_state: participant.handle.state,
        session_state: session.state,
    }))
}

#[cfg(target_os = "linux")]
async fn wait_for_cancel_world_work_closeout(
    store: &AgentRuntimeStateStore,
    orchestration_session_id: &str,
    participant_id: &str,
) -> Result<RetainedWorkerCancelCloseoutV1> {
    let started_at = Instant::now();
    loop {
        let participant = store.load_participant(participant_id)?.ok_or_else(|| {
            anyhow::anyhow!(
                "missing_target_participant: retained worker {} disappeared before durable cancel closeout was observed",
                participant_id
            )
        })?;
        let session = store
            .load_orchestration_session(orchestration_session_id)?
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "missing_orchestration_session: orchestration session {} disappeared before durable cancel closeout was observed",
                    orchestration_session_id
                )
            })?;
        if participant.has_cancelled_terminal_truth() && session.has_cancelled_terminal_truth() {
            return Ok(RetainedWorkerCancelCloseoutV1 {
                participant_state: Some(participant.handle.state),
                session_state: Some(session.state),
            });
        }
        if !participant.handle.state.is_live() && !participant.has_cancelled_terminal_truth() {
            anyhow::bail!(
                "cancel_closeout_failed: retained worker {} reached terminal state {} instead of cancelled",
                participant_id,
                participant.reviewable_terminal_state_label()
            );
        }
        if session.state.is_terminal() && !session.has_cancelled_terminal_truth() {
            anyhow::bail!(
                "cancel_closeout_failed: orchestration session {} reached terminal state {} instead of cancelled",
                orchestration_session_id,
                session.reviewable_terminal_state_label()
            );
        }
        if started_at.elapsed() >= STOP_WORLD_WORKER_CLOSEOUT_WAIT_TIMEOUT {
            anyhow::bail!(
                "owner_unreachable: timed out waiting for retained worker {} to reach durable cancelled closeout",
                participant_id
            );
        }
        tokio::time::sleep(STOP_WORLD_WORKER_CLOSEOUT_POLL_INTERVAL).await;
    }
}

#[cfg(target_os = "linux")]
fn detached_stop_world_worker_closeout_available(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    transport_path: &Path,
    transport_error: Option<&anyhow::Error>,
) -> bool {
    let owner_continuity = store
        .classify_hidden_owner_helper_launch_continuity(
            &resolved.session.orchestration_session_id,
            resolved.caller_participant.participant_id(),
            true,
        )
        .ok();
    let detached_owner_unreachable = matches!(
        owner_continuity,
        Some(
            crate::execution::agent_runtime::state_store::HiddenOwnerHelperLaunchContinuity::DetachedReconciled(
                _
            ) | crate::execution::agent_runtime::state_store::HiddenOwnerHelperLaunchContinuity::StaleAttachedTruth
        )
    );
    if let Some(err) = transport_error {
        let refused_live_transport =
            transport_path.exists() && detached_stop_transport_is_unusable(err);
        if refused_live_transport && parked_retained_target_stop_transport_contradiction(resolved) {
            return true;
        }
        if !detached_owner_unreachable {
            return false;
        }
        return !transport_path.exists() || detached_stop_transport_is_unusable(err);
    }

    if !detached_owner_unreachable {
        return false;
    }

    !transport_path.exists()
}

#[cfg(target_os = "linux")]
fn detached_stop_transport_is_unusable(err: &anyhow::Error) -> bool {
    private_stop_transport_error_kind(err) == Some(std::io::ErrorKind::ConnectionRefused)
}

#[cfg(target_os = "linux")]
fn stop_world_worker_sanctioned_recovery_retry_available(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    transport_path: &Path,
    initial_result: &Result<PrivateStopOutcome>,
) -> Result<bool> {
    let qualifies_current_owner_delivery_refusal = match initial_result {
        Ok(PrivateStopOutcome::OwnerUnreachable) => true,
        Err(err) => {
            matches!(
                private_stop_transport_error_kind(err),
                Some(std::io::ErrorKind::ConnectionRefused)
            ) || (!transport_path.exists()
                && private_stop_transport_error_kind(err) == Some(std::io::ErrorKind::NotFound))
        }
        Ok(_) => false,
    };
    if !qualifies_current_owner_delivery_refusal {
        return Ok(false);
    }
    if observed_stop_world_worker_closeout(
        store,
        &resolved.session.orchestration_session_id,
        resolved.target_participant.participant_id(),
    )
    .ok()
    .flatten()
    .is_some()
    {
        return Ok(false);
    }

    let refreshed_sanctioned = refreshed_sanctioned_stop_world_dispatch_target(store, resolved)?;
    if let (Err(err), Some(refreshed)) = (initial_result.as_ref(), refreshed_sanctioned.as_ref()) {
        if refused_exact_target_stop_transport_proves_current_attached_owner_stale(
            resolved,
            refreshed,
            transport_path,
            err,
        ) {
            return Ok(false);
        }
    }

    Ok(refreshed_sanctioned.is_some())
}

#[cfg(target_os = "linux")]
fn refreshed_sanctioned_stop_world_dispatch_target(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
) -> Result<
    Option<crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget>,
> {
    let session = match store.load_orchestration_session(&resolved.session.orchestration_session_id)
    {
        Ok(Some(session)) => session,
        Ok(None) => return Ok(None),
        Err(err) => return Err(err),
    };
    let Some(authoritative_caller_participant_id) = session.sanctioned_stop_owner_participant_id()
    else {
        return Ok(None);
    };
    let refreshed_resolved = store.resolve_internal_stop_world_dispatch_target(
        &resolved.session.orchestration_session_id,
        authoritative_caller_participant_id,
        resolved.target_participant.participant_id(),
        &resolved.target_participant.handle.backend_id,
    )?;
    resolved.ensure_exact_target_match(&refreshed_resolved)?;
    Ok(Some(refreshed_resolved))
}

#[cfg(target_os = "linux")]
fn refreshed_detached_exact_stop_world_dispatch_target(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
) -> Result<
    Option<crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget>,
> {
    let session = match store.load_orchestration_session(&resolved.session.orchestration_session_id)
    {
        Ok(Some(session)) => session,
        Ok(None) => return Ok(None),
        Err(err) => return Err(err),
    };
    if session.state
        != crate::execution::agent_runtime::orchestration_session::OrchestrationSessionState::Active
    {
        return Ok(None);
    }
    if session.posture
        == crate::execution::agent_runtime::orchestration_session::OrchestrationSessionPosture::ActiveAttached
    {
        return Ok(None);
    }

    let record = match store.load_session(&resolved.session.orchestration_session_id) {
        Ok(Some(record)) => record,
        Ok(None) => return Ok(None),
        Err(err) => return Err(err),
    };
    debug_assert_eq!(
        record.session.orchestration_session_id, session.orchestration_session_id,
        "detached exact-target refresh must keep authoritative session identity aligned"
    );
    Ok(Some(resolved.project_refreshed_exact_target(record)?))
}

#[cfg(target_os = "linux")]
fn detached_stop_world_worker_closeout_available_after_transport_failure(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    transport_path: &Path,
    transport_error: &anyhow::Error,
) -> Result<bool> {
    // The refreshed re-resolution path is only intended for the stale live-socket seam:
    // we saw a stop socket, attempted delivery, and got ECONNREFUSED while session truth
    // may have flipped to parked resumable during that wait window.
    if !transport_path.exists() || !detached_stop_transport_is_unusable(transport_error) {
        return Ok(false);
    }

    let refreshed_sanctioned = refreshed_sanctioned_stop_world_dispatch_target(store, resolved)?;
    if refreshed_sanctioned.as_ref().is_some_and(|refreshed| {
        refused_exact_target_stop_transport_proves_current_attached_owner_stale(
            resolved,
            refreshed,
            transport_path,
            transport_error,
        )
    }) {
        return Ok(true);
    }
    let refreshed_resolved = if let Some(refreshed) = refreshed_sanctioned {
        Some(refreshed)
    } else {
        refreshed_detached_exact_stop_world_dispatch_target(store, resolved)?
    };
    let Some(refreshed_resolved) = refreshed_resolved else {
        return Ok(false);
    };

    Ok(detached_stop_world_worker_closeout_available(
        store,
        &refreshed_resolved,
        transport_path,
        Some(transport_error),
    ))
}

#[cfg(target_os = "linux")]
fn refused_exact_target_stop_transport_proves_current_attached_owner_stale(
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    refreshed: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    transport_path: &Path,
    transport_error: &anyhow::Error,
) -> bool {
    transport_path.exists()
        && detached_stop_transport_is_unusable(transport_error)
        && refreshed.session.state
            == crate::execution::agent_runtime::orchestration_session::OrchestrationSessionState::Active
        && refreshed.session.posture
            == crate::execution::agent_runtime::orchestration_session::OrchestrationSessionPosture::ActiveAttached
        && refreshed.session.active_participant_id()
            == Some(resolved.caller_participant.participant_id())
        && refreshed.session.attached_participant_id()
            == Some(resolved.caller_participant.participant_id())
        && refreshed.caller_participant.participant_id()
            == resolved.caller_participant.participant_id()
}

#[cfg(target_os = "linux")]
fn parked_retained_target_stop_transport_contradiction(
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
) -> bool {
    resolved.session.state == crate::execution::agent_runtime::orchestration_session::OrchestrationSessionState::Active
        && resolved.session.posture
            == crate::execution::agent_runtime::orchestration_session::OrchestrationSessionPosture::ParkedResumable
        && resolved.target_participant.handle.execution.scope == AgentExecutionScope::World
        && resolved.target_participant.handle.state.is_live()
        && resolved.target_participant.internal.terminal_observed_at.is_none()
        && !resolved.target_participant.is_resume_eligible()
        && resolved.target_participant.internal.control_owner_retained
        && resolved.target_participant.internal.event_stream_active
        && resolved
            .target_participant
            .internal
            .completion_observer_retained
        && resolved.target_participant.internal.ownership_valid
        && matches!(
            resolved.target_participant.internal.ownership_mode,
            Some(
                crate::execution::agent_runtime::session::AgentRuntimeOwnershipMode::MemberRuntime
            )
        )
}

#[cfg(target_os = "linux")]
fn persist_detached_stop_world_worker_closeout(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
) -> Result<RetainedWorkerStopCloseoutV1> {
    let refreshed_resolved = if let Some(refreshed_resolved) =
        refreshed_sanctioned_stop_world_dispatch_target(store, resolved)?
    {
        refreshed_resolved
    } else if let Some(refreshed_resolved) =
        refreshed_detached_exact_stop_world_dispatch_target(store, resolved)?
    {
        refreshed_resolved
    } else {
        let session = store
            .load_orchestration_session(&resolved.session.orchestration_session_id)?
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "missing_orchestration_session: orchestration session {} disappeared before detached durable stop closeout could be persisted",
                    resolved.session.orchestration_session_id
                )
            })?;
        let authoritative_caller_participant_id =
            session.sanctioned_stop_owner_participant_id().ok_or_else(|| {
                anyhow::anyhow!(
                    "stale_linkage: orchestration session {} lost its sanctioned stop owner before detached durable stop closeout could be persisted",
                    resolved.session.orchestration_session_id
                )
            })?;
        store.resolve_internal_stop_world_dispatch_target(
            &resolved.session.orchestration_session_id,
            authoritative_caller_participant_id,
            resolved.target_participant.participant_id(),
            &resolved.target_participant.handle.backend_id,
        )?
    };
    // Preserve the original exact retained-worker contract across owner rebinding.
    // Detached fallback may no longer have a sanctioned owner to re-resolve through,
    // but the retained worker tuple must still remain exact.
    resolved.ensure_exact_target_match(&refreshed_resolved)?;
    let mut session = refreshed_resolved.session;
    let mut participant = refreshed_resolved.target_participant;

    persist_runtime_stop_closeout(store, &mut session, &mut participant)
        .context("failed to persist detached durable stop closeout for retained worker")?;

    Ok(RetainedWorkerStopCloseoutV1 {
        participant_state: participant.handle.state,
        session_state: session.state,
    })
}

#[cfg(target_os = "linux")]
fn summarize_stop_world_worker_result(
    participant_id: &str,
    backend_id: &str,
    used_private_stop_surface: bool,
) -> String {
    if used_private_stop_surface {
        return format!(
            "stop_world_worker drove durable stopped closeout for retained worker {participant_id} on backend {backend_id} via the existing private owner stop surface"
        );
    }

    format!(
        "stop_world_worker drove durable stopped closeout for retained worker {participant_id} on backend {backend_id} via detached durable closeout because the retained runtime owner was no longer reachable"
    )
}

#[cfg(target_os = "linux")]
fn stop_world_worker_recovery_failed(detail: impl AsRef<str>) -> anyhow::Error {
    anyhow::anyhow!(
        "owner_unreachable: recovery_failed: {}",
        detail.as_ref().trim()
    )
}

#[cfg(target_os = "linux")]
fn summarize_cancel_world_work_result(participant_id: &str, backend_id: &str) -> String {
    format!(
        "cancel_world_work drove durable cancelled closeout for retained worker {participant_id} on backend {backend_id} via the dedicated private owner cancel surface"
    )
}

#[cfg(target_os = "linux")]
fn summarize_active_ephemeral_cancel_world_task_result(
    task_run_id: &str,
    backend_id: &str,
) -> String {
    format!(
        "cancel_world_work interrupted active ephemeral task {task_run_id} on backend {backend_id} via the existing /v1/execute/cancel surface without reopening retained worker lifecycle state"
    )
}

#[cfg(target_os = "linux")]
fn active_ephemeral_cancel_signal(payload: &WorkerCancelPayloadV1) -> &'static str {
    if payload.graceful == Some(false) {
        "TERM"
    } else {
        "INT"
    }
}

#[cfg(target_os = "linux")]
fn agent_runtime_session_state_label(state: &AgentRuntimeSessionState) -> &'static str {
    match state {
        AgentRuntimeSessionState::Allocating => "allocating",
        AgentRuntimeSessionState::Ready => "ready",
        AgentRuntimeSessionState::Running => "running",
        AgentRuntimeSessionState::Restarting => "restarting",
        AgentRuntimeSessionState::Stopping => "stopping",
        AgentRuntimeSessionState::Stopped => "stopped",
        AgentRuntimeSessionState::Failed => "failed",
        AgentRuntimeSessionState::Invalidated => "invalidated",
    }
}

