    #[cfg(target_os = "linux")]
    fn write_fake_continue_world_worker_runtime(temp: &Path) -> std::path::PathBuf {
        let path = temp.join("fake-continue-world-worker-runtime.sh");
        let state_file = temp.join("continue-world-worker.count");
        let body = format!(
            "#!/bin/sh\nSTATE_FILE='{}'\nif [ \"${{1-}}\" = \"--version\" ]; then\n  printf 'codex 1.2.3\\n'\n  exit 0\nfi\nif [ \"${{1-}}\" = \"features\" ] && [ \"${{2-}}\" = \"list\" ]; then\n  if [ \"${{3-}}\" = \"--json\" ]; then\n    printf '{{\"features\":[\"add_dir\"]}}\\n'\n  else\n    printf 'add_dir\\n'\n  fi\n  exit 0\nfi\nif [ \"${{1-}}\" = \"--help\" ]; then\n  printf 'Usage: codex --add-dir\\n'\n  exit 0\nfi\ncount=0\nif [ -f \"$STATE_FILE\" ]; then\n  count=$(cat \"$STATE_FILE\")\nfi\ncount=$((count + 1))\nprintf '%s' \"$count\" > \"$STATE_FILE\"\nif [ \"$count\" -eq 1 ]; then\n  trap 'exit 0' INT TERM HUP QUIT\n  printf '{{\"type\":\"thread.started\",\"thread_id\":\"thread-real\"}}\\r\\n'\n  printf '{{\"type\":\"turn.started\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-1\"}}\\r\\n'\n  while :; do sleep 1; done\nfi\nif [ \"$count\" -eq 2 ]; then\n  printf '{{\"type\":\"thread.resumed\",\"thread_id\":\"thread-real\"}}\\r\\n'\n  printf '{{\"type\":\"turn.started\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-2\"}}\\r\\n'\n  printf '{{\"type\":\"item.completed\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-2\",\"item_id\":\"msg-2\",\"status\":\"completed\",\"item_type\":\"agent_message\",\"content\":{{\"text\":\"reply from live runtime\"}}}}\\r\\n'\n  printf '{{\"type\":\"turn.completed\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-2\",\"last_item_id\":\"msg-2\"}}\\r\\n'\n  exit 0\nfi\nif [ \"$count\" -eq 3 ]; then\n  printf '{{\"type\":\"thread.resumed\",\"thread_id\":\"thread-real\"}}\\r\\n'\n  printf '{{\"type\":\"turn.started\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-3\"}}\\r\\n'\n  printf '{{\"type\":\"item.started\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-3\",\"item_id\":\"cmd-3\",\"status\":\"in_progress\",\"item_type\":\"command_execution\",\"content\":{{\"command\":\"echo hi\"}}}}\\r\\n'\n  printf '{{\"type\":\"turn.completed\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-3\",\"last_item_id\":\"cmd-3\"}}\\r\\n'\n  exit 0\nfi\nprintf '{{\"type\":\"thread.resumed\",\"thread_id\":\"thread-real\"}}\\r\\n'\nprintf '{{\"type\":\"turn.started\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-4\"}}\\r\\n'\nprintf '{{\"type\":\"turn.failed\",\"thread_id\":\"thread-real\",\"turn_id\":\"turn-4\",\"error\":{{\"message\":\"boom\"}}}}\\r\\n'\nexit 1\n",
            state_file.display()
        );
        fs::write(&path, body).expect("write fake continue runtime");
        let mut perms = fs::metadata(&path)
            .expect("fake continue runtime metadata")
            .permissions();
        use std::os::unix::fs::PermissionsExt;
        perms.set_mode(0o755);
        fs::set_permissions(&path, perms).expect("set fake continue runtime permissions");
        path
    }

    #[cfg(target_os = "linux")]
    async fn read_http_request(stream: &mut tokio::net::UnixStream) -> Option<(String, Vec<u8>)> {
        let mut buf = Vec::new();
        let mut header_end = None;
        let mut expected_len = None;

        for _ in 0..64 {
            let mut tmp = [0u8; 1024];
            let n =
                tokio::time::timeout(std::time::Duration::from_millis(250), stream.read(&mut tmp))
                    .await
                    .ok()?
                    .ok()?;
            if n == 0 {
                break;
            }
            buf.extend_from_slice(&tmp[..n]);

            if header_end.is_none() {
                if let Some(pos) = buf.windows(4).position(|window| window == b"\r\n\r\n") {
                    header_end = Some(pos + 4);
                    let header = String::from_utf8_lossy(&buf[..pos + 4]).to_string();
                    expected_len = header.lines().find_map(|line| {
                        let (key, value) = line.split_once(':')?;
                        if key.eq_ignore_ascii_case("content-length") {
                            value.trim().parse::<usize>().ok()
                        } else {
                            None
                        }
                    });
                }
            }

            match (header_end, expected_len) {
                (Some(header_end), Some(len)) if buf.len() >= header_end + len => {
                    let header = String::from_utf8_lossy(&buf[..header_end]).to_string();
                    let body = buf[header_end..header_end + len].to_vec();
                    return Some((header, body));
                }
                (Some(header_end), None) => {
                    let header = String::from_utf8_lossy(&buf[..header_end]).to_string();
                    return Some((header, Vec::new()));
                }
                _ => {}
            }
        }

        None
    }

    #[cfg(target_os = "linux")]
    async fn write_http_json(stream: &mut tokio::net::UnixStream, status_line: &str, body: &str) {
        let response = format!(
            "HTTP/1.1 {status_line}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            body.len(),
            body
        );
        let _ = stream.write_all(response.as_bytes()).await;
        let _ = stream.shutdown().await;
    }

    #[cfg(target_os = "linux")]
    async fn write_http_body(
        stream: &mut tokio::net::UnixStream,
        status_line: &str,
        content_type: &str,
        body: &[u8],
    ) {
        let response = format!(
            "HTTP/1.1 {status_line}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
            body.len()
        );
        let _ = stream.write_all(response.as_bytes()).await;
        let _ = stream.write_all(body).await;
        let _ = stream.shutdown().await;
    }

    #[cfg(target_os = "linux")]
    async fn terminate_test_server(
        server: tokio::task::JoinHandle<()>,
        label: &str,
    ) -> Result<(), String> {
        server.abort();
        match server.await {
            Err(error) if error.is_cancelled() => Ok(()),
            Ok(()) => Ok(()),
            Err(error) => Err(format!("{label} server join failed unexpectedly: {error}")),
        }
    }

    #[cfg(target_os = "linux")]
    enum TestBodyOutcome<T> {
        Completed(T),
        Panicked(Box<dyn std::any::Any + Send>),
        CleanupFailed(String),
    }

    #[cfg(target_os = "linux")]
    impl<T> TestBodyOutcome<T> {
        fn finish(self) -> T {
            match self {
                Self::Completed(value) => value,
                Self::Panicked(payload) => std::panic::resume_unwind(payload),
                Self::CleanupFailed(error) => panic!("{error}"),
            }
        }
    }

    #[cfg(target_os = "linux")]
    async fn run_test_body_with_server_cleanup<T, TestFuture, Cleanup, CleanupFuture>(
        server: tokio::task::JoinHandle<()>,
        socket_home: TempDir,
        socket_path: &Path,
        label: &str,
        test: TestFuture,
        cleanup: Cleanup,
    ) -> TestBodyOutcome<T>
    where
        TestFuture: std::future::Future<Output = T>,
        Cleanup: FnOnce() -> CleanupFuture,
        CleanupFuture: std::future::Future<Output = ()>,
    {
        let test_outcome = std::panic::AssertUnwindSafe(test).catch_unwind().await;
        let server_outcome = terminate_test_server(server, label).await;
        let cleanup_outcome = std::panic::AssertUnwindSafe(async { cleanup().await })
            .catch_unwind()
            .await;
        drop(socket_home);
        let fixture_outcome = (!socket_path.exists())
            .then_some(())
            .ok_or_else(|| format!("{label} socket fixture survived confirmed server termination"));

        if let Err(error) = server_outcome {
            return TestBodyOutcome::CleanupFailed(error);
        }
        if let Err(payload) = cleanup_outcome {
            return TestBodyOutcome::Panicked(payload);
        }
        if let Err(error) = fixture_outcome {
            return TestBodyOutcome::CleanupFailed(error);
        }
        match test_outcome {
            Ok(value) => TestBodyOutcome::Completed(value),
            Err(payload) => TestBodyOutcome::Panicked(payload),
        }
    }

    #[cfg(target_os = "linux")]
    #[derive(Clone, Default)]
    struct TestTaskRegistry {
        tasks: Arc<Mutex<Vec<RegisteredTestTask>>>,
    }

    #[cfg(target_os = "linux")]
    struct RegisteredTestTask {
        abort: tokio::task::AbortHandle,
        monitor: tokio::task::JoinHandle<TestTaskPosture>,
        cancellation_allowed: bool,
    }

    #[cfg(target_os = "linux")]
    struct TestTaskHandle<T> {
        abort: tokio::task::AbortHandle,
        result: tokio::sync::oneshot::Receiver<Result<T, tokio::task::JoinError>>,
    }

    #[cfg(target_os = "linux")]
    impl<T> TestTaskHandle<T> {
        fn abort(&self) {
            self.abort.abort();
        }

        fn is_finished(&self) -> bool {
            self.abort.is_finished()
        }
    }

    #[cfg(target_os = "linux")]
    struct TestTaskAbortOnDrop {
        abort: tokio::task::AbortHandle,
    }

    #[cfg(target_os = "linux")]
    impl TestTaskAbortOnDrop {
        fn new<T>(task: &TestTaskHandle<T>) -> Self {
            Self {
                abort: task.abort.clone(),
            }
        }
    }

    #[cfg(target_os = "linux")]
    impl Drop for TestTaskAbortOnDrop {
        fn drop(&mut self) {
            if !self.abort.is_finished() {
                self.abort.abort();
            }
        }
    }

    #[cfg(target_os = "linux")]
    impl<T> std::future::Future for TestTaskHandle<T> {
        type Output = Result<T, tokio::task::JoinError>;

        fn poll(
            mut self: std::pin::Pin<&mut Self>,
            cx: &mut std::task::Context<'_>,
        ) -> std::task::Poll<Self::Output> {
            match std::pin::Pin::new(&mut self.result).poll(cx) {
                std::task::Poll::Ready(Ok(result)) => std::task::Poll::Ready(result),
                std::task::Poll::Ready(Err(_)) => {
                    panic!("registered test task monitor dropped its result")
                }
                std::task::Poll::Pending => std::task::Poll::Pending,
            }
        }
    }

    #[cfg(target_os = "linux")]
    #[derive(Clone, Copy, Debug, Eq, PartialEq)]
    enum TestTaskPosture {
        Completed,
        Cancelled,
        Panicked,
    }

    #[cfg(target_os = "linux")]
    impl TestTaskRegistry {
        fn spawn<F>(&self, future: F) -> TestTaskHandle<F::Output>
        where
            F: std::future::Future + Send + 'static,
            F::Output: Send + 'static,
        {
            self.spawn_with_posture(future, false)
        }

        fn spawn_cancellable<F>(&self, future: F) -> TestTaskHandle<F::Output>
        where
            F: std::future::Future + Send + 'static,
            F::Output: Send + 'static,
        {
            self.spawn_with_posture(future, true)
        }

        fn spawn_with_posture<F>(
            &self,
            future: F,
            cancellation_allowed: bool,
        ) -> TestTaskHandle<F::Output>
        where
            F: std::future::Future + Send + 'static,
            F::Output: Send + 'static,
        {
            let task = tokio::spawn(future);
            let abort = task.abort_handle();
            let (result_tx, result_rx) = tokio::sync::oneshot::channel();
            let monitor = tokio::spawn(async move {
                let result = task.await;
                let posture = match &result {
                    Ok(_) => TestTaskPosture::Completed,
                    Err(err) if err.is_cancelled() => TestTaskPosture::Cancelled,
                    Err(_) => TestTaskPosture::Panicked,
                };
                let _ = result_tx.send(result);
                posture
            });
            self.tasks
                .lock()
                .expect("test task registry mutex poisoned")
                .push(RegisteredTestTask {
                    abort: abort.clone(),
                    monitor,
                    cancellation_allowed,
                });
            TestTaskHandle {
                abort,
                result: result_rx,
            }
        }

        async fn finish_or_abort_and_wait(&self) {
            let tasks = std::mem::take(
                &mut *self
                    .tasks
                    .lock()
                    .expect("test task registry mutex poisoned"),
            );
            let mut timed_out = false;
            let mut unexpected = Vec::new();
            for mut task in tasks {
                let posture = match timeout(Duration::from_secs(3), &mut task.monitor).await {
                    Ok(posture) => posture.expect("registered test task monitor panicked"),
                    Err(_) => {
                        timed_out = true;
                        task.abort.abort();
                        task.monitor
                            .await
                            .expect("registered test task monitor panicked after abort")
                    }
                };
                if posture == TestTaskPosture::Panicked
                    || (posture == TestTaskPosture::Cancelled && !task.cancellation_allowed)
                {
                    unexpected.push(posture);
                }
            }
            assert!(
                !timed_out,
                "registered test task required forced cancellation during cleanup"
            );
            assert!(
                unexpected.is_empty(),
                "registered test task ended with unexpected posture: {unexpected:?}"
            );
        }
    }

    #[cfg(target_os = "linux")]
    #[derive(Clone)]
    struct TestFixtureTaskOwner {
        tasks: TestTaskRegistry,
        close_tx: tokio::sync::watch::Sender<bool>,
        private_stop_paths: Arc<Mutex<Vec<PathBuf>>>,
    }

    #[cfg(target_os = "linux")]
    impl TestFixtureTaskOwner {
        fn new() -> Self {
            let (close_tx, _close_rx) = tokio::sync::watch::channel(false);
            Self {
                tasks: TestTaskRegistry::default(),
                close_tx,
                private_stop_paths: Arc::new(Mutex::new(Vec::new())),
            }
        }

        fn close_receiver(&self) -> tokio::sync::watch::Receiver<bool> {
            self.close_tx.subscribe()
        }

        fn spawn<F>(&self, future: F)
        where
            F: std::future::Future<Output = ()> + Send + 'static,
        {
            let _task = self.tasks.spawn(future);
        }

        fn spawn_cancellable<F>(&self, future: F) -> TestTaskHandle<F::Output>
        where
            F: std::future::Future + Send + 'static,
            F::Output: Send + 'static,
        {
            self.tasks.spawn_cancellable(future)
        }

        fn spawn_with_private_stop_path<F>(&self, path: PathBuf, future: F)
        where
            F: std::future::Future<Output = ()> + Send + 'static,
        {
            self.private_stop_paths
                .lock()
                .expect("test fixture private stop path mutex poisoned")
                .push(path);
            let _task = self.tasks.spawn(future);
        }

        async fn finish(&self) {
            self.close_tx.send_replace(true);
            self.tasks.finish_or_abort_and_wait().await;
            let surviving_paths = self
                .private_stop_paths
                .lock()
                .expect("test fixture private stop path mutex poisoned")
                .iter()
                .filter(|path| path.exists())
                .cloned()
                .collect::<Vec<_>>();
            assert!(
                surviving_paths.is_empty(),
                "private stop transports survived confirmed fixture task termination: {surviving_paths:?}"
            );
        }
    }

    #[cfg(target_os = "linux")]
    async fn wait_for_test_fixture_close(receiver: &mut tokio::sync::watch::Receiver<bool>) {
        while !*receiver.borrow() {
            receiver
                .changed()
                .await
                .expect("test fixture close owner must outlive its tasks");
        }
    }

    #[cfg(target_os = "linux")]
    async fn settle_test_fixture_server(
        server: tokio::task::JoinHandle<()>,
        label: &str,
    ) -> Result<(), String> {
        if !server.is_finished() {
            server.abort();
        }
        match server.await {
            Ok(()) => Ok(()),
            Err(error) if error.is_cancelled() => Ok(()),
            Err(error) => Err(format!("{label} server join failed unexpectedly: {error}")),
        }
    }

    #[cfg(target_os = "linux")]
    async fn run_test_body_with_fixture_task_cleanup<T, TestFuture>(
        server: tokio::task::JoinHandle<()>,
        socket_home: TempDir,
        socket_path: &Path,
        label: &str,
        fixture_tasks: TestFixtureTaskOwner,
        test: TestFuture,
    ) -> TestBodyOutcome<T>
    where
        TestFuture: std::future::Future<Output = T>,
    {
        let test_outcome = std::panic::AssertUnwindSafe(test).catch_unwind().await;
        let server_outcome = settle_test_fixture_server(server, label).await;
        let cleanup_outcome = std::panic::AssertUnwindSafe(fixture_tasks.finish())
            .catch_unwind()
            .await;
        drop(socket_home);
        let fixture_outcome = (!socket_path.exists())
            .then_some(())
            .ok_or_else(|| format!("{label} socket fixture survived confirmed task termination"));

        if let Err(error) = server_outcome {
            return TestBodyOutcome::CleanupFailed(error);
        }
        if let Err(payload) = cleanup_outcome {
            return TestBodyOutcome::Panicked(payload);
        }
        if let Err(error) = fixture_outcome {
            return TestBodyOutcome::CleanupFailed(error);
        }
        match test_outcome {
            Ok(value) => TestBodyOutcome::Completed(value),
            Err(payload) => TestBodyOutcome::Panicked(payload),
        }
    }

    #[cfg(target_os = "linux")]
    async fn write_http_stream_start(stream: &mut tokio::net::UnixStream) {
        let response = "HTTP/1.1 200 OK\r\nContent-Type: application/x-ndjson\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n";
        let _ = stream.write_all(response.as_bytes()).await;
        let _ = stream.flush().await;
    }

    #[cfg(target_os = "linux")]
    async fn write_chunked_bytes(stream: &mut tokio::net::UnixStream, payload: &[u8]) {
        let header = format!("{:X}\r\n", payload.len());
        let _ = stream.write_all(header.as_bytes()).await;
        let _ = stream.write_all(payload).await;
        let _ = stream.write_all(b"\r\n").await;
        let _ = stream.flush().await;
    }

    #[cfg(target_os = "linux")]
    async fn write_chunked_frame(
        stream: &mut tokio::net::UnixStream,
        frame: &transport_api_types::ExecuteStreamFrame,
    ) {
        let mut payload = serde_json::to_vec(frame).expect("serialize stream frame");
        payload.push(b'\n');
        write_chunked_bytes(stream, &payload).await;
    }

    #[cfg(target_os = "linux")]
    async fn finish_chunked_stream(stream: &mut tokio::net::UnixStream) {
        let _ = stream.write_all(b"0\r\n\r\n").await;
        let _ = stream.flush().await;
        let _ = stream.shutdown().await;
    }

    #[cfg(target_os = "linux")]
    async fn capture_spawn_member_dispatch_env(
        listener: UnixListener,
        expected_cwd: String,
    ) -> HashMap<String, String> {
        while let Ok((mut stream, _addr)) = listener.accept().await {
            let Some((header, body)) = read_http_request(&mut stream).await else {
                continue;
            };
            let first_line = header.lines().next().unwrap_or("");
            if first_line.starts_with("GET /v1/capabilities ") {
                write_http_json(
                    &mut stream,
                    "200 OK",
                    r#"{"schema_version":1,"policy_snapshot_v1_supported":true}"#,
                )
                .await;
                continue;
            }
            if !first_line.starts_with("POST /v1/execute/stream ") {
                write_http_json(&mut stream, "404 Not Found", r#"{"error":"not_found"}"#).await;
                continue;
            }

            let execute_request: ExecuteRequest =
                serde_json::from_slice(&body).expect("member dispatch execute request");
            assert_eq!(
                execute_request.cwd.as_deref(),
                Some(expected_cwd.as_str()),
                "Spawn must use the authoritative workspace root",
            );
            let env = execute_request.env.clone().unwrap_or_default();
            let member_dispatch = execute_request
                .member_dispatch
                .expect("Spawn request includes member dispatch");
            write_http_stream_start(&mut stream).await;
            write_chunked_frame(
                &mut stream,
                &transport_api_types::ExecuteStreamFrame::Start {
                    frame_identity: test_runtime_frame_identity(1),
                    span_id: "spawn-principal-route".to_string(),
                },
            )
            .await;
            write_chunked_frame(
                &mut stream,
                &transport_api_types::ExecuteStreamFrame::Event {
                    frame_identity: test_runtime_frame_identity(2),
                    event: substrate_common::agent_events::AgentEvent {
                        ts: chrono::Utc::now(),
                        kind: AgentEventKind::Registered,
                        data: json!({}),
                        agent_id: execute_request.agent_id,
                        orchestration_session_id: member_dispatch.orchestration_session_id.clone(),
                        run_id: member_dispatch.run_id.clone(),
                        parent_run_id: None,
                        participant_id: Some(member_dispatch.participant_id.clone()),
                        parent_participant_id: None,
                        resumed_from_participant_id: None,
                        backend_id: Some(member_dispatch.backend_id.clone()),
                        thread_id: None,
                        role: Some("member".to_string()),
                        world_id: Some(member_dispatch.world_id.clone()),
                        world_generation: Some(member_dispatch.world_generation),
                        cmd_id: None,
                        span_id: Some("spawn-principal-route".to_string()),
                        event_identity: Some(test_runtime_event_identity(1)),
                        worker_event: None,
                        channel: None,
                        identity_tuple: None,
                        placement_posture: None,
                        project: None,
                    },
                },
            )
            .await;
            finish_chunked_stream(&mut stream).await;
            return env;
        }
        panic!("Spawn member-dispatch fixture ended before execute request");
    }

    #[cfg(target_os = "linux")]
    async fn next_stream_frame_value<B>(body: &mut B, buffer: &mut Vec<u8>) -> serde_json::Value
    where
        B: HttpBody<Data = hyper014::body::Bytes> + Unpin,
        B::Error: std::fmt::Debug + std::fmt::Display,
    {
        loop {
            if let Some(pos) = buffer.iter().position(|&b| b == b'\n') {
                let line: Vec<u8> = buffer.drain(..=pos).collect();
                let payload = &line[..line.len() - 1];
                return serde_json::from_slice(payload).expect("valid stream frame json value");
            }

            let chunk = timeout(std::time::Duration::from_secs(5), body.data())
                .await
                .expect("timed out waiting for stream chunk")
                .expect("stream ended unexpectedly")
                .expect("stream chunk error");
            buffer.extend_from_slice(&chunk);
        }
    }

    #[cfg(target_os = "linux")]
    fn frame_start_span_id(frame: &serde_json::Value) -> Option<&str> {
        if frame.get("type")?.as_str() == Some("start") {
            return frame.get("span_id")?.as_str();
        }
        frame.get("Start")?.get("span_id")?.as_str()
    }

    #[cfg(target_os = "linux")]
    fn frame_event(frame: &serde_json::Value) -> Option<&serde_json::Value> {
        if frame.get("type").and_then(serde_json::Value::as_str) == Some("event") {
            return frame.get("event");
        }
        frame.get("Event")?.get("event")
    }

    #[cfg(target_os = "linux")]
    async fn next_registered_frame<B>(body: &mut B, buffer: &mut Vec<u8>) -> serde_json::Value
    where
        B: HttpBody<Data = hyper014::body::Bytes> + Unpin,
        B::Error: std::fmt::Debug + std::fmt::Display,
    {
        loop {
            let frame = next_stream_frame_value(body, buffer).await;
            if let Some(event) = frame_event(&frame) {
                if event.get("kind").and_then(serde_json::Value::as_str) == Some("registered") {
                    return frame;
                }
            }
        }
    }

